#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define MAX_RECORD_SIZE 4096
#define SERIAL_MAGIC 0xDEADF00D
#define STATE_RUNNING 1
#define STATE_DRAINING 2
#define STATE_STOPPED 3

typedef struct {
    unsigned int magic;
    unsigned int version;
    unsigned int payload_len;
    unsigned int checksum;
} record_header_t;

typedef struct {
    int state;
    pthread_mutex_t lock;
    char *output_path;
    int pending_writes;
    int fd;
} serializer_ctx_t;

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static unsigned int compute_checksum(const void *data, size_t len) {
    unsigned int csum = 0;
    const unsigned char *p = (const unsigned char *)data;
    for (size_t i = 0; i < len; i++) {
        csum = (csum << 3) ^ (csum >> 29) ^ p[i];
    }
    return csum;
}

static int validate_output_path(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        return -1;
    }
    if (st.st_uid != getuid()) {
        return -1;
    }
    return 0;
}

static int open_output_file(serializer_ctx_t *ctx) {
    if (validate_output_path(ctx->output_path) != 0) {
        fprintf(stderr, "Path validation failed: %s\n", ctx->output_path);
        return -1;
    }
    /* Window between validate and open - TOCTOU */
    ctx->fd = open(ctx->output_path, O_WRONLY | O_APPEND);
    if (ctx->fd < 0) {
        perror("open");
        return -1;
    }
    return 0;
}

static int serialize_record(serializer_ctx_t *ctx, const void *data, size_t len) {
    if (len > MAX_RECORD_SIZE) {
        return -1;
    }
    pthread_mutex_lock(&ctx->lock);
    if (ctx->state != STATE_RUNNING) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    ctx->pending_writes++;
    pthread_mutex_unlock(&ctx->lock);

    record_header_t hdr;
    hdr.magic = SERIAL_MAGIC;
    hdr.version = 1;
    hdr.payload_len = (unsigned int)len;
    hdr.checksum = compute_checksum(data, len);

    if (ctx->fd < 0) {
        if (open_output_file(ctx) != 0) {
            pthread_mutex_lock(&ctx->lock);
            ctx->pending_writes--;
            pthread_mutex_unlock(&ctx->lock);
            return -1;
        }
    }

    ssize_t written = write(ctx->fd, &hdr, sizeof(hdr));
    if (written != sizeof(hdr)) {
        pthread_mutex_lock(&ctx->lock);
        ctx->pending_writes--;
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    written = write(ctx->fd, data, len);
    if (written != (ssize_t)len) {
        pthread_mutex_lock(&ctx->lock);
        ctx->pending_writes--;
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_lock(&ctx->lock);
    ctx->pending_writes--;
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

static int graceful_shutdown(serializer_ctx_t *ctx) {
    pthread_mutex_lock(&ctx->lock);
    ctx->state = STATE_DRAINING;
    pthread_mutex_unlock(&ctx->lock);

    int retries = 50;
    while (retries-- > 0) {
        pthread_mutex_lock(&ctx->lock);
        int pending = ctx->pending_writes;
        pthread_mutex_unlock(&ctx->lock);
        if (pending == 0) break;
        usleep(10000);
    }

    pthread_mutex_lock(&ctx->lock);
    ctx->state = STATE_STOPPED;
    if (ctx->fd >= 0) {
        close(ctx->fd);
        ctx->fd = -1;
    }
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

static serializer_ctx_t* serializer_init(const char *path) {
    serializer_ctx_t *ctx = calloc(1, sizeof(serializer_ctx_t));
    if (!ctx) return NULL;
    ctx->state = STATE_RUNNING;
    ctx->fd = -1;
    ctx->output_path = strdup(path);
    pthread_mutex_init(&ctx->lock, NULL);
    return ctx;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <output_file>\n", argv[0]);
        return 1;
    }
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    serializer_ctx_t *ctx = serializer_init(argv[1]);
    if (!ctx) return 1;

    const char *sample = "test record payload data";
    while (!shutdown_requested) {
        serialize_record(ctx, sample, strlen(sample));
        usleep(100000);
    }

    graceful_shutdown(ctx);
    free(ctx->output_path);
    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
    return 0;
}
